1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * The identity of an owner's household: its {@code lastName} and {@code address} compared
10	 * case-insensitively, with surrounding whitespace stripped and internal runs collapsed to a single
11	 * space. The {@code address} is additionally run through the shared {@link OwnerAddress} normalization
12	 * (upper-casing and expanding abbreviations), so a stored normalized address and a raw one match.
13	 * Two owners belong to the same household when their {@code OwnerHousehold} values are equal.
14	 *
15	 * <p>This is the single definition of "same household" shared by {@link CheckOwnerHouseholdUnique}
16	 * (which iterates to reject a second owner joining a household) and {@link AssignHousehold} (which
17	 * iterates to find the donor owner whose {@code householdId} a new member inherits). Changing the
18	 * matching rule — e.g. trimming punctuation or including city — happens here, once.
19	 */
20	public record OwnerHousehold(String lastName, String address) {
21	
22	    public OwnerHousehold {
23	        lastName = normalize(lastName);
24	        address = OwnerAddress.normalize(address);
25	    }
26	
27	    public static OwnerHousehold of(Owner owner) {
28	        return new OwnerHousehold(owner.getLastName(), owner.getAddress());
29	    }
30	
31	    public static OwnerHousehold of(OwnerFieldsDto fields) {
32	        return new OwnerHousehold(fields.getLastName(), fields.getAddress());
33	    }
34	
35	    /** Lower-cases and collapses whitespace so comparison ignores case and incidental spacing. */
36	    private static String normalize(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
