1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.UUID;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Runs after {@link BuildOwner} on {@code POST /api/owners} and assigns the new owner's stable
12	 * {@code householdId}.
13	 *
14	 * <p>When the request opted in via {@code sharesHousehold} true, the new owner joins an existing
15	 * household: the first already-persisted owner in the same household (see {@link OwnerHousehold})
16	 * donates its {@code householdId} so both owners share one identifier. Otherwise (not sharing, or
17	 * sharing with no existing household to join) a fresh random identifier is minted so every owner
18	 * always has a non-blank {@code householdId}.
19	 */
20	public class AssignHousehold {
21	
22	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            OwnerHousehold household = OwnerHousehold.of(owner);
25	            for (Owner existing : ownerRepository.findAll()) {
26	                if (existing.getHouseholdId() != null && household.equals(OwnerHousehold.of(existing))) {
27	                    owner.setHouseholdId(existing.getHouseholdId());
28	                    return;
29	                }
30	            }
31	        }
32	        owner.setHouseholdId(UUID.randomUUID().toString());
33	    }
34	}
