1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;
8	
9	/**
10	 * Runs after {@link ValidateOwner} and before {@link BuildOwner}. Rejects the create with a 409 via
11	 * {@link OwnerHouseholdDuplicateException} when another owner already belongs to the same household
12	 * (same lastName and address — see {@link OwnerHousehold} for how that is compared).
13	 *
14	 * <p>The request may opt out of this rule by setting {@code sharesHousehold} true, which permits
15	 * creating a second owner in the same household; {@link AssignHousehold} then gives the new owner the
16	 * existing household's identifier.
17	 */
18	public class CheckOwnerHouseholdUnique {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerHouseholdDuplicateException {
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return; // opted in to sharing a household; skip the duplicate check
24	        }
25	        OwnerHousehold household = OwnerHousehold.of(request);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (household.equals(OwnerHousehold.of(existing))) {
28	                throw new OwnerHouseholdDuplicateException(request.getLastName(), request.getAddress());
29	            }
30	        }
31	    }
32	}
