1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	public class BuildOwner {
10	
11	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
12	        Owner owner = ownerMapper.toOwner(request);
13	        // The effective registration date (supplied or defaulted) must fall on a business day: a
14	        // weekend rolls forward to Monday, so every value derived from it uses the adjusted date.
15	        owner.setRegistrationDate(BusinessDay.effective(owner.getRegistrationDate()));
16	        built.set(owner);
17	    }
18	}
